import logging
from functools import partial
from taf.rfrl.utilities.robot.RobotThreads import RobotThreads
from taf.rfrl.utilities.robot.RobotKWRunner import run_as_robot_kw as convert_to_robot_kw


def run_parallel_in_robot(list_of_functions):
    """
    Run functions in parallel
    :param list_of_functions: list of functions to run
    [
        {
            'function': <function>,
            'function_kwargs': <function_kwargs>,
            'device_name': <device_name>,
            'raise_exception': <raise_exception[True|False]>.  # if not defined False

        },
        {
            'function': <function2>,
            'function_kwargs': <function_kwargs2>,
            'device_name': <device_name>,
        },
    ]

    """
    with RobotThreads() as threads:
        active_threads = []
        for function_dict in list_of_functions:
            function = function_dict['function']
            function_kwargs = function_dict['function_kwargs']
            device_name = function_dict['device_name']
            raise_exception = function_dict.get('raise_exception', False)
            thread_name = "Thread::{}::{}".format(device_name, function.__name__.upper())
            custom_repr_name = device_name + "::" + function.__name__.replace('_', ' ').title()

            robot_function = partial(convert_to_robot_kw, function, custom_repr_name=custom_repr_name,
                                     **function_kwargs)
            if thread_name in active_threads:
                raise Exception("Thread {} already running - please check your code".format(thread_name))
            threads.create_thread(thread_name=thread_name, function=robot_function, raise_exception=raise_exception)
            active_threads.append(thread_name)
        threads.wait_until_all_threads_finished()
        logging.debug("Results: {}".format(threads.thread_results))
        threads.raise_exception_if_any_thread_failed(full_traceback=True)
        return threads.thread_results
